mapper.select:
SELECT esub.*,
       u.name AS studentName,
       e.title AS examTitle
FROM exam_submissions esub
LEFT JOIN users u ON esub.student_id = u.id
LEFT JOIN exams e ON esub.exam_id = e.id
WHERE 1=1
AND esub.exam_id = #{examId}
AND esub.student_id = #{studentId}
AND esub.graded = #{graded}
ORDER BY ${sortBy} ${order}
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM exam_submissions
WHERE 1=1
AND exam_id = #{examId}
AND student_id = #{studentId}
AND graded = #{graded}
